mutation LoginRestaurant($loginDto: LoginDto!) {
  LoginRestaurant(loginDto: $loginDto) {
    accessToken
    refreshToken
    restaurant {
      id
      name
      address
      menuItems { id name price available }
    }
    error { message }
  }
}

mutation Login($email: String!, $password: String!) {
  Login(email: $email, password: $password) {
    accessToken
    refreshToken
    user { id name email }
    error { message }
  }
}

